CREATE OR REPLACE FUNCTION public.strip_sensitive_user_metadata() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $function$ BEGIN NEW.raw_user_meta_data := COALESCE(NEW.raw_user_meta_data, '{}'::jsonb) - 'security_answer' - 'securityAnswer'; RETURN NEW; END; $function$; REVOKE ALL ON FUNCTION public.strip_sensitive_user_metadata() FROM PUBLIC, anon, authenticated; CREATE TRIGGER strip_sensitive_user_metadata BEFORE INSERT OR UPDATE OF raw_user_meta_data ON auth.users FOR EACH ROW EXECUTE FUNCTION public.strip_sensitive_user_metadata(); ALTER TABLE public.profiles ADD CONSTRAINT profiles_security_answer_must_be_null CHECK (security_answer IS NULL);